package com.grantora.service;

import com.grantora.entity.*;
import com.grantora.repository.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.stream.Collectors;

@Service
public class Milestone3ReportService {
    private final UserRepository users;private final GrantApplicationRepository applications;private final DisbursementPlanRepository plans;
    private final MilestoneComplianceRepository compliances;private final ComplianceNonComplianceRepository cases;
    private final GrantUtilizationRepository utilization;private final SchemeRepository schemes;
    public Milestone3ReportService(UserRepository users,GrantApplicationRepository applications,DisbursementPlanRepository plans,
            MilestoneComplianceRepository compliances,ComplianceNonComplianceRepository cases,GrantUtilizationRepository utilization,SchemeRepository schemes){
        this.users=users;this.applications=applications;this.plans=plans;this.compliances=compliances;this.cases=cases;this.utilization=utilization;this.schemes=schemes;
    }
    @Transactional(readOnly=true)
    public String csv(String type,String email,LocalDate from,LocalDate to,Long schemeId,String state,String district,String appStatus,String disbStatus){
        User actor=users.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found."));
        if(actor.getRole()!=Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Report export is restricted to administrators.");
        if(from!=null&&to!=null&&from.isAfter(to))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Start date must be on or before end date.");
        Map<Long,DisbursementPlan> planByApp=plans.findAllByOrderByCreatedAtDesc().stream().collect(Collectors.toMap(p->p.getApplication().getId(),p->p,(a,b)->a));
        List<GrantApplication> apps=applications.findAllByOrderByIdDesc().stream().filter(a->matches(a,planByApp.get(a.getId()),from,to,schemeId,state,district,appStatus,disbStatus)).toList();
        Set<Long> ids=apps.stream().map(GrantApplication::getId).collect(Collectors.toSet());
        return switch(type.toLowerCase(Locale.ROOT)){
            case "disbursement"->disbursement(apps,planByApp);
            case "compliance"->compliance(apps,ids);
            case "utilization"->utilization(apps,ids,planByApp);
            case "regional"->regional(apps,ids,planByApp);
            default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown report type.");
        };
    }
    private String disbursement(List<GrantApplication> apps,Map<Long,DisbursementPlan> plans){StringBuilder b=start("Application Reference,Beneficiary,Scheme,Application Status,Approved Amount,Installment,Installment Amount,Planned Release Date,Actual Release Date,Installment Status,Released Amount,Pending Amount,Disbursement Status");for(GrantApplication a:apps){DisbursementPlan p=plans.get(a.getId());List<DisbursementInstallment> active=p==null?List.of():p.getInstallments().stream().filter(i->i.getStatus()!=InstallmentStatus.CANCELLED).toList();BigDecimal released=sum(active.stream().filter(i->i.getStatus()==InstallmentStatus.DISBURSED).map(DisbursementInstallment::getAmount).toList());BigDecimal approved=a.getStatus()==GrantApplicationStatus.APPROVED?a.getRequestedAmount():BigDecimal.ZERO;BigDecimal pending=approved.subtract(released).max(BigDecimal.ZERO);if(active.isEmpty())line(b,appRef(a),beneficiary(a),a.getScheme().getSchemeName(),a.getStatus(),approved,"","","","",released,pending,ds(p));else for(int index=0;index<active.size();index++){DisbursementInstallment i=active.get(index);line(b,appRef(a),beneficiary(a),a.getScheme().getSchemeName(),a.getStatus(),index==0?approved:"",i.getInstallmentNumber(),i.getAmount(),i.getPlannedReleaseDate(),i.getActualDisbursementDate(),i.getStatus()==InstallmentStatus.DISBURSED?i.getAmount():BigDecimal.ZERO,index==0?pending:"",ds(p));}}return b.toString();}
    private String compliance(List<GrantApplication> apps,Set<Long> ids){StringBuilder b=start("Application Reference,Beneficiary,Scheme,Installment,Requirement,Required,Deadline,Status,Submitted At,Officer Remarks,Non-Compliance Status,Severity,Reason,Detected At");Map<Long,ComplianceNonCompliance> caseMap=cases.findAllByOrderByDetectedAtDesc().stream().collect(Collectors.toMap(c->c.getCompliance().getId(),c->c,(a,c)->a));for(MilestoneCompliance c:compliances.findAll()){GrantApplication a=c.getMilestone().getInstallment().getPlan().getApplication();if(!ids.contains(a.getId()))continue;ComplianceNonCompliance nc=caseMap.get(c.getId());line(b,appRef(a),beneficiary(a),a.getScheme().getSchemeName(),c.getMilestone().getInstallment().getInstallmentNumber(),c.getRequirementTitle(),c.isRequired(),c.getSubmissionDeadline(),c.getStatus(),c.getSubmittedAt(),c.getVerificationRemarks(),nc==null?"":nc.getStatus(),nc==null?"":nc.getSeverity(),nc==null?"":nc.getReason(),nc==null?"":nc.getDetectedAt());}return b.toString();}
    private String utilization(List<GrantApplication> apps,Set<Long> ids,Map<Long,DisbursementPlan> plans){StringBuilder b=start("Application Reference,Beneficiary,Scheme,Application Status,Approved Amount,Scheduled Amount,Released Amount,Reported Expenditure,Verified Expenditure,Remaining Released Balance,Disbursement Status");List<GrantUtilizationRecord> records=utilization.findAllByOrderBySubmittedAtDesc().stream().filter(r->ids.contains(r.getApplication().getId())).toList();for(GrantApplication a:apps){DisbursementPlan p=plans.get(a.getId());List<DisbursementInstallment> is=p==null?List.of():p.getInstallments().stream().filter(i->i.getStatus()!=InstallmentStatus.CANCELLED).toList();List<GrantUtilizationRecord> ur=records.stream().filter(r->Objects.equals(r.getApplication().getId(),a.getId())).toList();BigDecimal approved=a.getStatus()==GrantApplicationStatus.APPROVED?a.getRequestedAmount():BigDecimal.ZERO;BigDecimal scheduled=p==null||p.getPlanStatus()==DisbursementPlanStatus.CANCELLED?BigDecimal.ZERO:sum(is.stream().map(DisbursementInstallment::getAmount).toList());BigDecimal released=sum(is.stream().filter(i->i.getStatus()==InstallmentStatus.DISBURSED).map(DisbursementInstallment::getAmount).toList());BigDecimal reported=sum(ur.stream().map(GrantUtilizationRecord::getReportedAmount).toList());BigDecimal verified=sum(ur.stream().filter(r->r.getStatus()==GrantUtilizationStatus.VERIFIED).map(GrantUtilizationRecord::getReportedAmount).toList());line(b,appRef(a),beneficiary(a),a.getScheme().getSchemeName(),a.getStatus(),approved,scheduled,released,reported,verified,released.subtract(reported),ds(p));}return b.toString();}
    private String regional(List<GrantApplication> apps,Set<Long> ids,Map<Long,DisbursementPlan> plans){Map<Long,Scheme> schemeMap=schemes.findAll().stream().collect(Collectors.toMap(Scheme::getId,s->s));List<GrantUtilizationRecord> records=utilization.findAllByOrderBySubmittedAtDesc().stream().filter(r->ids.contains(r.getApplication().getId())).toList();Map<String,List<GrantApplication>> groups=apps.stream().collect(Collectors.groupingBy(a->location(a.getBeneficiary()==null?null:a.getBeneficiary().getState())+"\u001f"+location(a.getBeneficiary()==null?null:a.getBeneficiary().getDistrict())+"\u001f"+a.getScheme().getId()));StringBuilder b=start("State,District,Scheme,Scheme Allocation,Applications,Approved Applications,Rejected Applications,Approved Amount,Released Amount,Reported Expenditure,Verified Expenditure,Pending Disbursement");Set<Long> allocationWritten=new HashSet<>();for(List<GrantApplication> group:groups.values()){GrantApplication first=group.get(0);Set<Long> groupIds=group.stream().map(GrantApplication::getId).collect(Collectors.toSet());List<DisbursementPlan> ps=plans.values().stream().filter(p->groupIds.contains(p.getApplication().getId())).toList();List<DisbursementInstallment> is=ps.stream().filter(p->p.getPlanStatus()!=DisbursementPlanStatus.CANCELLED).flatMap(p->p.getInstallments().stream()).filter(i->i.getStatus()!=InstallmentStatus.CANCELLED).toList();List<GrantUtilizationRecord> rs=records.stream().filter(r->groupIds.contains(r.getApplication().getId())).toList();BigDecimal approved=sum(group.stream().filter(a->a.getStatus()==GrantApplicationStatus.APPROVED).map(GrantApplication::getRequestedAmount).toList());BigDecimal released=sum(is.stream().filter(i->i.getStatus()==InstallmentStatus.DISBURSED).map(DisbursementInstallment::getAmount).toList());BigDecimal reported=sum(rs.stream().map(GrantUtilizationRecord::getReportedAmount).toList());BigDecimal verified=sum(rs.stream().filter(r->r.getStatus()==GrantUtilizationStatus.VERIFIED).map(GrantUtilizationRecord::getReportedAmount).toList());Scheme scheme=schemeMap.get(first.getScheme().getId());Object allocation=allocationWritten.add(scheme.getId())?zero(scheme.getAllocatedFunds()):"";line(b,location(first.getBeneficiary()==null?null:first.getBeneficiary().getState()),location(first.getBeneficiary()==null?null:first.getBeneficiary().getDistrict()),scheme.getSchemeName(),allocation,group.size(),group.stream().filter(a->a.getStatus()==GrantApplicationStatus.APPROVED).count(),group.stream().filter(a->a.getStatus()==GrantApplicationStatus.REJECTED).count(),approved,released,reported,verified,approved.subtract(released).max(BigDecimal.ZERO));}return b.toString();}
    private boolean matches(GrantApplication a,DisbursementPlan p,LocalDate from,LocalDate to,Long schemeId,String state,String district,String appStatus,String disbStatus){if(schemeId!=null&&!Objects.equals(a.getScheme().getId(),schemeId))return false;if(from!=null&&(a.getSubmittedAt()==null||a.getSubmittedAt().toLocalDate().isBefore(from)))return false;if(to!=null&&(a.getSubmittedAt()==null||a.getSubmittedAt().toLocalDate().isAfter(to)))return false;if(state!=null&&!state.isBlank()&&!location(a.getBeneficiary()==null?null:a.getBeneficiary().getState()).equalsIgnoreCase(state.trim()))return false;if(district!=null&&!district.isBlank()&&!location(a.getBeneficiary()==null?null:a.getBeneficiary().getDistrict()).equalsIgnoreCase(district.trim()))return false;if(appStatus!=null&&!appStatus.isBlank()&&!a.getStatus().name().equalsIgnoreCase(appStatus.trim()))return false;return disbStatus==null||disbStatus.isBlank()||ds(p).equalsIgnoreCase(disbStatus.trim());}
    private String ds(DisbursementPlan p){if(p==null)return "UNPLANNED";if(p.getPlanStatus()==DisbursementPlanStatus.CANCELLED)return "CANCELLED";List<DisbursementInstallment> is=p.getInstallments().stream().filter(i->i.getStatus()!=InstallmentStatus.CANCELLED).toList();if(is.isEmpty())return "NO_ACTIVE_INSTALLMENTS";if(is.stream().allMatch(i->i.getStatus()==InstallmentStatus.DISBURSED))return "COMPLETED";if(is.stream().anyMatch(i->i.getStatus()==InstallmentStatus.ON_HOLD))return "ON_HOLD";if(is.stream().anyMatch(i->i.getStatus()==InstallmentStatus.READY_FOR_DISBURSEMENT))return "READY_FOR_RELEASE";return "PLANNED";}
    private String appRef(GrantApplication a){return "APP-"+a.getId();}private String beneficiary(GrantApplication a){return a.getBeneficiary()==null||a.getBeneficiary().getUser()==null?"":a.getBeneficiary().getUser().getFullName();}private String location(String x){return x==null||x.isBlank()?"Not provided":x.trim();}private BigDecimal zero(BigDecimal x){return x==null?BigDecimal.ZERO:x;}private BigDecimal sum(List<BigDecimal> xs){return xs.stream().filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);}
    private StringBuilder start(String header){return new StringBuilder("\uFEFF").append(header).append("\r\n");}
    private void line(StringBuilder b,Object... values){for(int i=0;i<values.length;i++){if(i>0)b.append(',');Object raw=values[i];String value=raw==null?"":raw.toString();if(raw instanceof String&&value.matches("^[\\t\\r ]*[=+@-].*"))value="'"+value;b.append('"').append(value.replace("\"","\"\"")).append('"');}b.append("\r\n");}
}
